import json, re, urllib.request, time

proteins = json.load(open('/app/fpbase_proteins.json'))
pdb_ids = set(open('/app/pdb_ids.txt').read().split())

print("=== FPbase proteins with em_max=610 AND PDB in our list ===")
for p in proteins:
    for s in p.get('states',[]):
        if s.get('em_max') == 610:
            pbs = set(str(x).upper() for x in p.get('pdb',[]))
            common = pbs & pdb_ids
            if common:
                print(f"  MATCH: name={p['name']}, slug={p['slug']}, pdb={p.get('pdb')}, ex={s.get('ex_max')}, em={s.get('em_max')}")
                print(f"  seq={p.get('seq','')}")
                print(f"  seq_len={len(p.get('seq',''))}")

print("\n=== ALL FPbase proteins with em_max=610 (first 30) ===")
count = 0
for p in proteins:
    for s in p.get('states',[]):
        if s.get('em_max') == 610:
            print(f"  name={p['name']}, slug={p['slug']}, pdb={p.get('pdb',[])}, ex={s.get('ex_max')}, em={s.get('em_max')}")
            count += 1
            if count >= 30:
                break
    if count >= 30:
        break

print("\n=== FPbase entries named mCherry or with pdb 2H5Q ===")
for p in proteins:
    if p['name'].lower() == 'mcherry' or '2H5Q' in [str(x).upper() for x in p.get('pdb',[])]:
        states = [(s.get('ex_max'), s.get('em_max'), s.get('slug')) for s in p.get('states',[])]
        print(f"  name={p['name']}, slug={p['slug']}, pdb={p.get('pdb',[])}, states={states}")
        print(f"  seq={p.get('seq','')}")
        print(f"  seq_len={len(p.get('seq',''))}")

# BLAST results
rids = {'heavy_v':'4EEM8H02014', 'light_v':'4EEMAE00014'}
for name, rid in rids.items():
    for attempt in range(4):
        url = f"https://blast.ncbi.nlm.nih.gov/blast/Blast.cgi?CMD=Get&RID={rid}&FORMAT_TYPE=XML&ALIGNMENTS=20"
        try:
            req = urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
            with urllib.request.urlopen(req, timeout=30) as r:
                data = r.read().decode(errors='replace')
            if 'Status=WAITING' in data or 'Status=QUEUED' in data or 'Status=PENDING' in data or 'Status=UNKNOWN' in data:
                print(f"\n{name}: RID={rid} still waiting (attempt {attempt+1})")
                time.sleep(8)
                continue
            hits = re.findall(r'<Hit_def>(.*?)</Hit_def>', data, re.DOTALL)
            accessions = re.findall(r'<Hit_accession>(.*?)</Hit_accession>', data, re.DOTALL)
            print(f"\n=== {name} BLAST hits ===")
            for i, (hdef, acc) in enumerate(zip(hits, accessions)):
                hdef_clean = re.sub(r'<[^>]+>', '', hdef)
                print(f"  {i+1}. {acc}: {hdef_clean[:150]}")
                if i >= 15:
                    break
            break
        except Exception as e:
            print(f"\n{name}: ERROR {e}")
            time.sleep(5)

# Sequence comparison
text = open('/app/pdb_fastas.txt').read()
pdb_fastas = {}
for m in re.finditer(r'>(\S+)_\d+\|([^\n]*)\n([A-Z\n]+)', text):
    pid = m.group(1)
    desc = m.group(2)
    seq = m.group(3).replace('\n','')
    if pid not in pdb_fastas:
        pdb_fastas[pid] = []
    pdb_fastas[pid].append((desc, seq))

for pid in ['5WJ2', '2H5Q', '3KZY']:
    print(f"\nPDB {pid}:")
    for desc, seq in pdb_fastas.get(pid, []):
        print(f"  desc: {desc}")
        print(f"  seq: {seq}")
        print(f"  len: {len(seq)}")

for pname in ['Clover', 'mCherry']:
    for p in proteins:
        if p['name'] == pname:
            print(f"\nfpbase {pname}:")
            print(f"  seq: {p.get('seq','')}")
            print(f"  len: {len(p.get('seq',''))}")
            break
